script:
// Hálózati térkép: egy csomag útja (ping) a legrövidebb úton, kapcsolat bontható
// Network map: a packet (ping) takes the shortest path; a link can be cut
stage(1000, 600, "#fbfbf8");
title({hu: "Hálózati térkép – egy csomag útja", en: "Network map – the path of a packet"});

// Az eszközök: név, típus, IP-cím, hely a vásznon / the devices: name, type, IP address, place on the canvas
const DEV = {
  net:  {name: "Internet",    kind: "cloud",   ip: "8.8.8.8",       x: 500, y: 95},
  rtr:  {name: "Router",      kind: "router",  ip: "192.168.1.1",   x: 500, y: 215},
  swA:  {name: "Switch A",    kind: "switch",  ip: "—",             x: 280, y: 330},
  swB:  {name: "Switch B",    kind: "switch",  ip: "—",             x: 720, y: 330},
  pc1:  {name: "PC 1",        kind: "pc",      ip: "192.168.1.11",  x: 140, y: 470},
  pc2:  {name: "PC 2",        kind: "pc",      ip: "192.168.1.12",  x: 330, y: 480},
  srv:  {name: "Server",      kind: "server",  ip: "192.168.1.20",  x: 640, y: 480},
  prn:  {name: "Printer",     kind: "printer", ip: "192.168.1.30",  x: 860, y: 470},
};
// Kábelek (kétirányúak) / cables (both ways)
const LINKS = [["net", "rtr"], ["rtr", "swA"], ["rtr", "swB"], ["swA", "swB"],
               ["swA", "pc1"], ["swA", "pc2"], ["swB", "srv"], ["swB", "prn"]];

const hosts = ["pc1", "pc2", "srv", "prn", "net"].map(id => [id, DEV[id].name]);
choice("src", {hu: "Feladó", en: "Sender"}, hosts, "pc1", {key: "f"});
choice("dst", {hu: "Címzett", en: "Destination"}, hosts, "prn", {key: "c"});
toggle("cut", {hu: "Switch A – Switch B kábel elvágva", en: "Switch A – Switch B cable cut"}, false, {key: "x"});
param("v", {hu: "Csomag sebessége", en: "Packet speed"}, 50, 600, 250, 10, "px/s");
resetOn("src", "dst", "cut");

const isCut = (a, b) => P.cut && ((a === "swA" && b === "swB") || (a === "swB" && b === "swA"));

// Szélességi keresés (BFS): a legkevesebb ugrásból álló út / breadth-first search: the path with the fewest hops
function shortestPath(from, to) {
  const prev = {[from]: null}, queue = [from];
  while (queue.length) {
    const u = queue.shift();
    if (u === to) break;
    for (const [a, b] of LINKS) {
      if (isCut(a, b)) continue;
      const w = a === u ? b : b === u ? a : null;     // a kábel másik vége / the other end of the cable
      if (w && !(w in prev)) { prev[w] = u; queue.push(w); }
    }
  }
  if (!(to in prev)) return null;
  const path = [];
  for (let n = to; n !== null; n = prev[n]) path.unshift(n);
  return path;
}

const path = shortestPath(P.src, P.dst);     // újraszámolva minden váltáskor (resetOn) / recomputed on every change
const pts = path ? path.map(id => [DEV[id].x, DEV[id].y]) : [];
let lengthPx = 0;
for (let k = 1; k < pts.length; k++) lengthPx += hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]);

let d = 0, back = false, wait = 0, pings = 0;   // megtett út (px), válasz megy-e, várakozás (s), sikeres pingek
update(dt => {
  if (!path || P.src === P.dst) return;
  if (wait > 0) { wait -= dt; return; }
  d += P.v * dt;
  if (d >= lengthPx) { d = 0; if (back) pings++; back = !back; wait = 0.4; }
});

// A pont helye az út mentén s px után / the point at distance s along the path
function pointAt(s) {
  for (let k = 1; k < pts.length; k++) {
    const seg = hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]);
    if (s <= seg) return [lerp(pts[k - 1][0], pts[k][0], s / seg), lerp(pts[k - 1][1], pts[k][1], s / seg)];
    s -= seg;
  }
  return pts[pts.length - 1];
}

// Egyszerű ikonok alakzatokból / simple icons made of shapes
function icon(dv) {
  const {x, y} = dv, st = {fill: "#fff", stroke: C.ink, lw: 2};
  if (dv.kind === "cloud")   { for (const [dx, r] of [[-30, 22], [0, 30], [30, 22]]) circle(x + dx, y, r, {fill: "#dbe9ff", stroke: null}); }
  if (dv.kind === "router")  { circle(x, y, 28, {fill: C.teal, stroke: C.ink}); text("⇄", x, y, {align: "center", baseline: "middle", size: 26, color: "#fff"}); }
  if (dv.kind === "switch")  { rect(x - 45, y - 15, 90, 30, {fill: C.blue, stroke: C.ink, radius: 4});
                               for (let k = 0; k < 6; k++) rect(x - 36 + k * 13, y - 4, 8, 8, {fill: "#fff", stroke: null}); }
  if (dv.kind === "pc")      { rect(x - 30, y - 28, 60, 40, st); rect(x - 24, y - 22, 48, 28, {fill: "#cfe8ff", stroke: null}); rect(x - 15, y + 14, 30, 6, {fill: C.ink}); }
  if (dv.kind === "server")  { rect(x - 22, y - 34, 44, 68, st); for (let k = 0; k < 4; k++) line(x - 14, y - 22 + k * 14, x + 14, y - 22 + k * 14, {stroke: C.gray}); }
  if (dv.kind === "printer") { rect(x - 32, y - 14, 64, 30, st); rect(x - 20, y - 30, 40, 16, st); rect(x - 20, y + 16, 40, 12, {fill: "#fff", stroke: C.gray}); }
  text(dv.name, x, y + 52, {align: "center", size: 15, bold: true});
  text(dv.ip, x, y + 70, {align: "center", size: 13, color: C.gray});
}

draw(t => {
  // 1) kábelek; az út kiemelve / cables, the path highlighted
  const onPath = (a, b) => path && path.some((id, k) => k > 0 && ((path[k - 1] === a && id === b) || (path[k - 1] === b && id === a)));
  for (const [a, b] of LINKS) {
    const A = DEV[a], Bd = DEV[b];
    if (isCut(a, b)) {
      line(A.x, A.y, Bd.x, Bd.y, {stroke: C.red, lw: 2, dash: [6, 6]});
      text("✂", (A.x + Bd.x) / 2, (A.y + Bd.y) / 2, {align: "center", baseline: "middle", size: 26, color: C.red});
    } else line(A.x, A.y, Bd.x, Bd.y, {stroke: onPath(a, b) ? C.orange : C.light, lw: onPath(a, b) ? 5 : 3});
  }
  // 2) eszközök / devices
  for (const id in DEV) icon(DEV[id]);
  // 3) a csomag: kérés kékkel oda, válasz zölddel vissza / the packet: request in blue, reply in green
  if (path && P.src !== P.dst) {
    const [px, py] = pointAt(back ? lengthPx - d : d);
    rect(px - 13, py - 9, 26, 18, {fill: back ? C.green : C.blue, stroke: C.ink, lw: 1.5, radius: 3});
    text(back ? {hu: "válasz", en: "reply"} : "ping", px, py - 16, {align: "center", size: 13, bold: true});
  }
  const route = path ? path.map(id => DEV[id].name).join(" → ") : tr({hu: "nincs út!", en: "no route!"});
  text(route, 500, 585, {align: "center", size: 16, color: path ? C.ink : C.red, bold: true});

  show({hu: "Útvonal", en: "Route"}, route);
  show({hu: "Ugrások száma", en: "Number of hops"}, path ? path.length - 1 : "—");
  show({hu: "Sikeres ping", en: "Successful pings"}, pings, "", 0);
});
